    verses = list(range(lo, hi + 1))
    sif_cites = [f'Sifrei Bamidbar {p}:{r}' for p in ps for r in range(1, SIF_ROWS[p] + 1)]
    cites = [f'Onkelos Num {c}:{v}' for v in verses] + sif_cites
    N = len(cites); NS = len(sif_cites)
    cnt = Counter(R[(c, v)][0] for v in verses); scnt = Counter(S[(p, r)][0] for p in ps for r in range(1, SIF_ROWS[p] + 1))
    placed = [p for p in ps if p in HEAD_FIX]
    sif_decl = (f' + the Sifrei on Numbers piskaot {ps[0]}-{ps[-1]} BY POSITION ({NS} rows at the shelf\'s row grain; every head asserted between its neighbors'
                + (f'; placed by position: {"; ".join(f"piska {p} → {HEAD_FIX[p][0]}:{HEAD_FIX[p][1]}" + (" (headless in the export)" if p == 59 else " (the export\'s head \'Ibid. 4\')" if p == 102 else f" (the export\'s head reads {heads[p][1]}:{heads[p][2]} — mistyped, RESEARCH_LOG.md)") for p in placed)}' if placed else '')
                + ('; piska 62 CREDITED — read at num_04_kehat\'s ledger 2026-09-09, its 8:24 arm consumed here' if 62 in ps else '') + ')')
    hdr = (f'# Numbers {c}:{lo}-{hi} derivation — Onkelos + the Sifrei on Numbers as the spine (its piskaot found BY POSITION), '
           f'THE NUMBERS WALK sitting 3 — BEHA\'ALOTCHA, {title} ({DATE}; the owner: "Ok continue to next numbers span", on the ruling NUMBERS IN ORDER FROM 1:1; chapter 9 FROZEN at THE TENT sitting 2 and SKIPPED). '
           f'DECLARED (THE_STEPS Step 2, the spine default of 2026-08-27, read at the PARASHAH GRAIN — speed ruling (a): one pass over Beha\'alotcha 8:1-12:16 less chapter 9, the four ledgers per block): scope = Onkelos Numbers {c}:{lo}-{hi} ({len(verses)} verses, fresh)'
           + sif_decl + f'. {TESTING[uid]} OUTSIDE DECLARED SCOPE, enumerated and unread (the shelf\'s other works on Numbers, {len(outside)} directories): {", ".join(outside)}.\n\n')
    body = f'## Sifrei Bamidbar piskaot {ps[0]}-{ps[-1]} ({NS} rows, read whole — the heads by position: {"; ".join(f"{p} on {head(p)[0]}:{head(p)[1]}" for p in ps)})\n'
    for p in ps:
        for r in range(1, SIF_ROWS[p] + 1):
            verdict, prose = S[(p, r)]
            body += f'- Sifrei Bamidbar {p}:{r} — {verdict}. {prose}\n'
    body += f'\n## Onkelos Numbers {c}:{lo}-{hi} ({len(verses)} verses, read whole)\n'
    for v in verses:
        verdict, prose = R[(c, v)]
        body += f'- Onkelos Num {c}:{v} — {verdict}. {prose}\n'
    body += '\n## The ink beside the shelf (computed by this script from the Tanakh DB, the snapshot store and the shelf — never recited)\n'
    for k in inks: body += INK[k] + '\n'
    body += register_line(c, lo, hi) + '\n'
    body += '\n## The finds (this ledger\'s crowns)\n' + '\n'.join(crowns) + '\n'
    body += (f'\n## CITE INDEX — every source opened, each fully named\n(one name per line; coverage COMPUTED against the shelf by the ledger script write_beha_ledgers.py: Onkelos Numbers {c}:{lo}-{hi} {len(verses)} verses — missing 0, extra 0; '
             f'the Sifrei on Numbers piskaot {ps[0]}-{ps[-1]}, {NS} rows at the shelf\'s own row counts — missing 0, extra 0' + ('; Sifrei Bamidbar 62:1 listed as CREDITED (its first read num_04_kehat_2026-09-09.md)' if 62 in ps else '') + ')\n')
    body += '\n'.join(cites) + '\n'
    fresh = NS - scnt['CREDITED']
    body += f'({len(verses)} Onkelos verses fresh + {fresh} Sifrei Bamidbar rows fresh' + (f' + {scnt["CREDITED"]} credited' if scnt['CREDITED'] else '') + f' = {N} sources in this ledger.)\n\n'
    body += (f'**read: {N} of {N} — COMPLETE** ({len(verses)} Onkelos verses and {NS} Sifrei rows opened and verdicted this sitting at the shelf\'s row grain, coverage computed by script — missing 0, extra 0; '
             f'verdicts MATERIAL {cnt["MATERIAL"]} Onkelos, CONTEXT {cnt["CONTEXT"]} Onkelos, MATERIAL {scnt["MATERIAL"]} Sifrei, CONTEXT {scnt["CONTEXT"]} Sifrei' + (f', CREDITED {scnt["CREDITED"]} Sifrei' if scnt['CREDITED'] else '') + ' — the counts the script\'s own Counter measured)\n')
    open(OUT[uid], 'w', encoding='utf-8').write(hdr + body)
    print(f'wrote {OUT[uid]}: {N} sources, Onkelos MATERIAL {cnt["MATERIAL"]} / CONTEXT {cnt["CONTEXT"]}; Sifrei {NS} rows MATERIAL {scnt["MATERIAL"]} / CONTEXT {scnt["CONTEXT"]} / CREDITED {scnt["CREDITED"]}')
    return N, cnt, scnt

